--
-- Table structure for table `items`
--

DROP TABLE IF EXISTS `items`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `items` (
  `id` bigint unsigned NOT NULL AUTO_INCREMENT,
  `position` int DEFAULT '0',
  `code` varchar(6) NOT NULL,
  `category_id` bigint unsigned NOT NULL,
  `url` varchar(120) NOT NULL,
  `name` varchar(120) NOT NULL,
  `description` text,
  `brand` varchar(50) DEFAULT NULL,
  `manufacturer_id` bigint unsigned NOT NULL,
  `price` varchar(50) DEFAULT NULL,
  `seo_title` text,
  `seo_description` text,
  `seo_keywords` text,
  `valute_id` bigint unsigned NOT NULL DEFAULT '1',
  `purchase_price` float DEFAULT NULL,
  `profitabilaty` float DEFAULT NULL,
  `price_postfix` varchar(50) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `id` (`id`),
  UNIQUE KEY `code` (`code`),
  UNIQUE KEY `url` (`url`),
  KEY `category_id` (`category_id`),
  KEY `manufacturer_id` (`manufacturer_id`),
  KEY `valute_id` (`valute_id`),
  CONSTRAINT `items_ibfk_1` FOREIGN KEY (`category_id`) REFERENCES `categories` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `items_ibfk_2` FOREIGN KEY (`manufacturer_id`) REFERENCES `countries` (`id`) ON DELETE CASCADE ON UPDATE CASCADE,
  CONSTRAINT `items_ibfk_3` FOREIGN KEY (`valute_id`) REFERENCES `valutes` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=1446 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

